catalog_script_client.script:
function onLoad() {
  // This function runs when the form is loaded. It recalculates the total number of onsite attendees
  // based on the values stored in the 'number_of_attendees' field (assumed to be a JSON string).

  function recalculateTotalAttendees() {
    var total = 0;

    // Parse the JSON stored in the 'number_of_attendees' field
    var rows = JSON.parse(g_form.getValue('number_of_attendees') || '[]');

    // Loop through each row and sum up the 'onsite' values
    rows.forEach(function(row) {
      var onsite = parseInt(row.onsite || 0);
      total += onsite;
    });

    // Set the total value in the 'total_number_of_onside_attendees' field
    g_form.setValue('total_number_of_onside_attendees', total);
  }

  // Call the function to recalculate totals
  recalculateTotalAttendees();
}
